using System.Runtime.CompilerServices;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.CSharp.Syntax;

namespace ArchLens.Extraction.Roslyn;

/// <summary>
/// Unified classifier for generated code (source generators, obj/, .g.cs, .designer.cs, &lt;auto-generated&gt;,
/// [GeneratedCode], [GeneratedRegex]) and infrastructure/structural types (EF Core migrations, DbContext,
/// System.Text.Json JsonSerializerContext).
/// </summary>
internal static class GeneratedCodeClassifier
{
    private static readonly ConditionalWeakTable<SyntaxTree, StrongBox<bool>> GeneratedTreeCache = new();

    private static readonly HashSet<string> GeneratedAttributeNames = new(StringComparer.Ordinal)
    {
        "GeneratedCodeAttribute",
        "GeneratedCode",
        "CompilerGeneratedAttribute",
        "CompilerGenerated",
        "GeneratedRegexAttribute",
        "GeneratedRegex"
    };

    public static bool IsGeneratedFilePath(string? filePath)
    {
        if (string.IsNullOrWhiteSpace(filePath))
        {
            return false;
        }

        var normalized = filePath.Replace('\\', '/');
        if (normalized.Contains("/obj/", StringComparison.OrdinalIgnoreCase) ||
            normalized.StartsWith("obj/", StringComparison.OrdinalIgnoreCase))
        {
            return true;
        }

        if (normalized.EndsWith(".g.cs", StringComparison.OrdinalIgnoreCase) ||
            normalized.EndsWith(".g.i.cs", StringComparison.OrdinalIgnoreCase) ||
            normalized.EndsWith(".designer.cs", StringComparison.OrdinalIgnoreCase) ||
            normalized.EndsWith(".generated.cs", StringComparison.OrdinalIgnoreCase) ||
            normalized.EndsWith(".i.cs", StringComparison.OrdinalIgnoreCase))
        {
            return true;
        }

        // Virtual source-generator paths emitted by Roslyn (e.g. System.Text.Json.SourceGeneration/.../Foo.g.cs)
        if (normalized.Contains("SourceGenerators/", StringComparison.OrdinalIgnoreCase) ||
            normalized.Contains("SourceGeneration/", StringComparison.OrdinalIgnoreCase) ||
            normalized.Contains("RazorSourceGenerator/", StringComparison.OrdinalIgnoreCase))
        {
            return true;
        }

        return false;
    }

    public static bool IsRazorGeneratedFilePath(string? filePath)
    {
        if (string.IsNullOrWhiteSpace(filePath))
        {
            return false;
        }

        var normalized = filePath.Replace('\\', '/');
        return normalized.EndsWith(".razor.g.cs", StringComparison.OrdinalIgnoreCase) ||
               normalized.EndsWith(".cshtml.g.cs", StringComparison.OrdinalIgnoreCase) ||
               normalized.Contains("RazorSourceGenerator", StringComparison.OrdinalIgnoreCase) ||
               normalized.Contains("Microsoft.NET.Sdk.Razor.SourceGenerators", StringComparison.OrdinalIgnoreCase);
    }

    public static bool IsMigrationFilePath(string? filePath)
    {
        if (string.IsNullOrWhiteSpace(filePath))
        {
            return false;
        }

        var normalized = filePath.Replace('\\', '/');
        return normalized.Contains("/Migrations/", StringComparison.OrdinalIgnoreCase) ||
               normalized.StartsWith("Migrations/", StringComparison.OrdinalIgnoreCase) ||
               normalized.EndsWith(".Designer.cs", StringComparison.OrdinalIgnoreCase);
    }

    public static bool IsGeneratedSyntaxTree(SyntaxTree? tree)
    {
        if (tree is null)
        {
            return false;
        }

        var box = GeneratedTreeCache.GetValue(tree, static t => new StrongBox<bool>(ComputeIsGeneratedSyntaxTree(t)));
        return box.Value;
    }

    private static bool ComputeIsGeneratedSyntaxTree(SyntaxTree tree)
    {
        if (IsGeneratedFilePath(tree.FilePath))
        {
            return true;
        }

        try
        {
            var root = tree.GetRoot();
            if (root.HasLeadingTrivia)
            {
                foreach (var trivia in root.GetLeadingTrivia())
                {
                    if (trivia.IsKind(SyntaxKind.SingleLineCommentTrivia) ||
                        trivia.IsKind(SyntaxKind.MultiLineCommentTrivia))
                    {
                        var text = trivia.ToString();
                        if (text.Contains("<auto-generated", StringComparison.OrdinalIgnoreCase) ||
                            text.Contains("<autogenerated", StringComparison.OrdinalIgnoreCase))
                        {
                            return true;
                        }
                    }
                }
            }

            // Also inspect leading trivia of the first token in case comment is attached there
            var firstToken = root.GetFirstToken();
            if (firstToken != default && firstToken.HasLeadingTrivia)
            {
                foreach (var trivia in firstToken.LeadingTrivia)
                {
                    if (trivia.IsKind(SyntaxKind.SingleLineCommentTrivia) ||
                        trivia.IsKind(SyntaxKind.MultiLineCommentTrivia))
                    {
                        var text = trivia.ToString();
                        if (text.Contains("<auto-generated", StringComparison.OrdinalIgnoreCase) ||
                            text.Contains("<autogenerated", StringComparison.OrdinalIgnoreCase))
                        {
                            return true;
                        }
                    }
                }
            }
        }
        catch
        {
            // Ignore syntax inspection errors
        }

        return false;
    }

    public static bool IsGeneratedSyntaxNode(SyntaxNode node)
    {
        if (IsGeneratedSyntaxTree(node.SyntaxTree))
        {
            return true;
        }

        SyntaxList<AttributeListSyntax> attrLists = node switch
        {
            MemberDeclarationSyntax member => member.AttributeLists,
            AccessorDeclarationSyntax accessor => accessor.AttributeLists,
            _ => default
        };

        foreach (var list in attrLists)
        {
            foreach (var attr in list.Attributes)
            {
                var name = attr.Name.ToString();
                var lastDot = name.LastIndexOf('.');
                var simple = lastDot >= 0 ? name[(lastDot + 1)..] : name;
                if (GeneratedAttributeNames.Contains(simple))
                {
                    return true;
                }
            }
        }

        return false;
    }

    public static bool HasGeneratedCodeAttribute(ISymbol symbol)
    {
        foreach (var attr in symbol.GetAttributes())
        {
            var name = attr.AttributeClass?.Name;
            if (name is not null && GeneratedAttributeNames.Contains(name))
            {
                return true;
            }
        }
        return false;
    }

    public static bool IsGeneratedOnlyType(INamedTypeSymbol type)
    {
        var sourceLocations = type.Locations.Where(l => l.IsInSource).ToList();
        if (sourceLocations.Count == 0)
        {
            return true;
        }

        if (sourceLocations.All(loc => IsGeneratedSyntaxTree(loc.SourceTree)))
        {
            return true;
        }

        // If every declaring syntax reference is marked with [GeneratedCode]/[CompilerGenerated]
        if (type.DeclaringSyntaxReferences.Length > 0 &&
            type.DeclaringSyntaxReferences.All(r => IsGeneratedSyntaxNode(r.GetSyntax())))
        {
            return true;
        }

        return false;
    }

    public static bool HasAnyGeneratedPart(INamedTypeSymbol type) =>
        type.DeclaringSyntaxReferences.Any(r => IsGeneratedSyntaxNode(r.GetSyntax()));

    public static bool IsMigrationOrSnapshotType(INamedTypeSymbol type)
    {
        for (var b = type.BaseType; b is not null && b.SpecialType == SpecialType.None; b = b.BaseType)
        {
            var full = b.ToDisplayString();
            if (full == "Microsoft.EntityFrameworkCore.Migrations.Migration" ||
                full == "Microsoft.EntityFrameworkCore.Infrastructure.ModelSnapshot")
            {
                return true;
            }
        }

        if (type.GetAttributes().Any(a => a.AttributeClass?.Name is "MigrationAttribute"))
        {
            return true;
        }

        var sourceLocations = type.Locations.Where(l => l.IsInSource).ToList();
        if (sourceLocations.Count > 0 && sourceLocations.All(l => IsMigrationFilePath(l.SourceTree?.FilePath)))
        {
            return true;
        }

        return false;
    }

    public static bool IsDbContextType(INamedTypeSymbol type)
    {
        for (var b = type.BaseType; b is not null && b.SpecialType == SpecialType.None; b = b.BaseType)
        {
            if (b.Name is "DbContext" or "IdentityDbContext" &&
                (b.ContainingNamespace?.ToDisplayString().StartsWith("Microsoft.EntityFrameworkCore", StringComparison.Ordinal) == true ||
                 b.ContainingNamespace?.ToDisplayString().StartsWith("Microsoft.AspNetCore.Identity.EntityFrameworkCore", StringComparison.Ordinal) == true))
            {
                return true;
            }
        }
        return false;
    }

    public static bool IsJsonSerializerContextType(INamedTypeSymbol type)
    {
        for (var b = type.BaseType; b is not null && b.SpecialType == SpecialType.None; b = b.BaseType)
        {
            if (b.Name == "JsonSerializerContext" &&
                b.ContainingNamespace?.ToDisplayString() == "System.Text.Json.Serialization")
            {
                return true;
            }
        }
        return false;
    }
}
